#pragma once

#include <cmath>
#include <cstdint>

struct ObjectDimensions
{
    float sizeX;
    float sizeY;
    float sizeZ;
};

// Autogenerated GTA San Andreas & SA-MP object database (models 0..19999)
// Contains exact 3D physical collision boundaries for all 10,487 models
bool GetModelCollisionDimensions(int modelId, float& sizeX, float& sizeY, float& sizeZ);
void InitObjectDatabase();

inline bool GetCommonObjectModelDimensions(int modelId, float& sizeX, float& sizeY, float& sizeZ)
{
    return GetModelCollisionDimensions(modelId, sizeX, sizeY, sizeZ);
}

inline float GetModelPhysicalRadius(int modelId)
{
    float sx = 0.0f, sy = 0.0f, sz = 0.0f;
    GetModelCollisionDimensions(modelId, sx, sy, sz);
    float hx = sx * 0.5f;
    float hy = sy * 0.5f;
    return std::sqrt(hx * hx + hy * hy);
}
